input.mermaid:
flowchart TD
    A[Start] --> B{Is the data processed?};
    B -- No --> C[Select feature/attribute];
    C --> D{Is this feature used as a split?};
    D -- Yes --> E{Split the data based on the feature's value};
    E --> F[Calculate impurity/information gain for each split];
    F --> G{Is the information gain high enough?};
    G -- No --> H[Do not split on this feature];
    G -- Yes --> I[Recurse on the resulting subsets];
    I --> J{Is a stopping criterion met? (e.g., max depth reached, pure node)};
    J -- No --> K[Repeat process (Select feature) on subsets];
    K --> J;
    J -- Yes --> L[Create a leaf node (Decision/Classification)];
    E --> M[Stop recursion (Leaf node)];
    L --> N[End];
    H --> O[Stop recursion (Leaf node)];
    M --> N;
    O --> N;
    A --> N;
